mapper.select:
SELECT record.*, cinema.name as cinemaName, room.name as roomName, room.seat_rows as roomSeatRows, room.seat_cols as roomSeatCols FROM record LEFT JOIN cinema ON record.cinema_id = cinema.id LEFT JOIN room ON record.room_id = room.id
AND record.title LIKE CONCAT('%', #{title}, '%') AND record.start LIKE CONCAT('%', #{start}, '%') AND record.status = #{status} AND record.cinema_id = #{cinemaId} AND record.room_id = #{roomId} AND record.film_id = #{filmId}
ORDER BY (record.start >= NOW()) DESC, record.start ASC, record.id ASC

mapper.update:
UPDATE record
cinema_id = #{cinemaId}, room_id = #{roomId}, film_id = #{filmId}, title = #{title}, start = #{start}, price = #{price}, status = #{status},
WHERE id = #{id}
